package botruntime

import (
	_ "embed"
	"github.com/killerprojecte/HumanEngine/backend/internal/jsjson"
	"math"
)

// Generated by running the real source Runtime. It includes the unchanged
// participation, planning, Replyer and exact-send validation system instructions.
//
//go:embed testdata/contracts.json
var contractsJSON []byte
var contracts *Object

func init() {
	v, e := jsjson.ParseBytes(contractsJSON)
	if e != nil {
		panic(e)
	}
	contracts = v.(*Object)
}
func contractTool(name string) *Object {
	return cloneJSON(get(get(contracts, "tools"), name)).(*Object)
}
func prompt(name string) string { return str(get(get(contracts, "prompts"), name)) }
func codePoints(s string) int {
	u, e := jsjson.UTF16(s)
	if e != nil {
		return -1
	}
	n := 0
	for i := 0; i < len(u); i++ {
		n++
		if u[i] >= 0xd800 && u[i] <= 0xdbff && i+1 < len(u) && u[i+1] >= 0xdc00 && u[i+1] <= 0xdfff {
			i++
		}
	}
	return n
}
func schemaValue(schema any, value any) (any, error) {
	fail := func() (any, error) { return nil, code("runtime_invalid_tool_input") }
	if options := array(get(schema, "oneOf")); len(options) > 0 {
		matches := 0
		var result any
		for _, option := range options {
			if value, err := schemaValue(option, value); err == nil {
				matches++
				result = value
			}
		}
		if matches != 1 {
			return fail()
		}
		return result, nil
	}
	if options := array(get(schema, "anyOf")); len(options) > 0 {
		for _, s := range options {
			if v, e := schemaValue(s, value); e == nil {
				return v, nil
			}
		}
		return fail()
	}
	if c := get(schema, "const"); c != nil && c != value {
		return fail()
	}
	if values := array(get(schema, "enum")); len(values) > 0 {
		found := false
		for _, v := range values {
			if v == value {
				found = true
			}
		}
		if !found {
			return fail()
		}
	}
	switch str(get(schema, "type")) {
	case "object":
		o, ok := value.(*Object)
		if !ok || o == nil {
			return fail()
		}
		properties, _ := get(schema, "properties").(*Object)
		out := obj()
		for _, key := range stringsOf(get(schema, "required")) {
			if _, ok := o.Get(key); !ok {
				property, _ := get(properties, key).(*Object)
				if property != nil {
					if _, hasDefault := property.Get("default"); hasDefault {
						continue
					}
				}
				return fail()
			}
		}
		if properties != nil {
			for _, m := range properties.Members() {
				v, has := o.Get(m.Key)
				if !has {
					if def, exists := m.Value.(*Object).Get("default"); exists {
						_ = out.Set(m.Key, cloneJSON(def))
					}
					continue
				}
				checked, e := schemaValue(m.Value, v)
				if e != nil {
					return nil, e
				}
				_ = out.Set(m.Key, checked)
			}
		}
		for _, m := range o.Members() {
			_, known := properties.Get(m.Key)
			if !known {
				if get(schema, "additionalProperties") == false {
					return fail()
				}
				_ = out.Set(m.Key, cloneJSON(m.Value))
			}
		}
		return out, nil
	case "array":
		a, ok := value.([]any)
		if !ok {
			return fail()
		}
		if n, ok := get(schema, "minItems").(float64); ok && float64(len(a)) < n {
			return fail()
		}
		if n, ok := get(schema, "maxItems").(float64); ok && float64(len(a)) > n {
			return fail()
		}
		out := []any{}
		for _, v := range a {
			x, e := schemaValue(get(schema, "items"), v)
			if e != nil {
				return nil, e
			}
			out = append(out, x)
		}
		return out, nil
	case "string":
		s, ok := value.(string)
		if !ok {
			return fail()
		}
		length := codePoints(s)
		if length < 0 {
			return fail()
		}
		if n, ok := get(schema, "minLength").(float64); ok && float64(length) < n {
			return fail()
		}
		if n, ok := get(schema, "maxLength").(float64); ok && float64(length) > n {
			return fail()
		}
	case "number", "integer":
		n, ok := value.(float64)
		if !ok || math.IsNaN(n) || math.IsInf(n, 0) {
			return fail()
		}
		if get(schema, "type") == "integer" && (math.Trunc(n) != n || math.Abs(n) > 9007199254740991) {
			return fail()
		}
		if min, ok := get(schema, "minimum").(float64); ok && n < min {
			return fail()
		}
		if max, ok := get(schema, "maximum").(float64); ok && n > max {
			return fail()
		}
	case "boolean":
		if _, ok := value.(bool); !ok {
			return fail()
		}
	}
	return cloneJSON(value), nil
}
func parseDecision(v any) (*Object, error) {
	x, e := schemaValue(get(contracts, "decisionSchema"), v)
	if e == nil {
		return x.(*Object), nil
	}
	o, ok := v.(*Object)
	if ok && codePoints(str(get(o, "reasonCode"))) > 200 {
		repaired := o.Clone()
		_ = repaired.Set("reasonCode", "planner_reason_omitted_over_limit")
		x, e = schemaValue(get(contracts, "decisionSchema"), repaired)
		if e == nil {
			return x.(*Object), nil
		}
	}
	return nil, e
}
